"""Generate or verify the C# embedded manifest-schema resource from Python."""

from __future__ import annotations

import argparse
import json
from pathlib import Path

from anyinfer.manifest import manifest_json_schema

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "src" / "csharp" / "AnyInfer" / "Manifest" / "manifest.schema.json"


def generated_bytes() -> bytes:
    """Return the canonical bytes generated by the public Python schema helper."""
    text = json.dumps(manifest_json_schema(), ensure_ascii=True, indent=2, sort_keys=True)
    return (text + "\n").encode("utf-8")


def is_current(path: Path = OUTPUT) -> bool:
    """Return whether a resource contains the exact generated bytes."""
    return path.is_file() and path.read_bytes() == generated_bytes()


def write(path: Path = OUTPUT) -> None:
    """Write the public helper's current schema bytes to the embedded-resource path."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(generated_bytes())


def main(argv: list[str] | None = None) -> int:
    """Generate the resource or fail when its bytes have drifted."""
    parser = argparse.ArgumentParser(description=__doc__)
    action = parser.add_mutually_exclusive_group(required=True)
    action.add_argument("--write", action="store_true", help="write the generated resource")
    action.add_argument(
        "--check", action="store_true", help="require the generated resource to match"
    )
    arguments = parser.parse_args(argv)

    if arguments.write:
        write()
        return 0
    if is_current():
        return 0
    print(f"{OUTPUT.relative_to(ROOT)} differs from manifest_json_schema(); run --write.")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
